// Prepare Audio Payload for Algerian Darija (Gemini AI & Whisper API compatible)
const binaryData = items[0].binary?.data;
if (!binaryData) {
  throw new Error('No audio/video file provided in binary property "data"');
}

const base64Audio = binaryData.data;
const mimeType = binaryData.mimeType || 'audio/mp3';
const query = $input.item.json.query || {};
const dialect = query.dialect || 'General Algerian';

// Whisper API & Local Whisper Grounding Glossary Prompt
const initialPrompt = "Redfield, PPF, aucun résidu de colle, résidu de colle, sans trace de colle, premier test, la nouvelle technologie PPF, vraiment, النتيجة, ولا كاش خطر, المستوى الوطني, المستوى الإفريقي, وكان الشرف لشركة";

const prompt = `You are an expert transcriber specialized in Algerian Arabic (الدارجة الجزائرية - Darija) and Franco-Algerian code-switching.
Listen to the audio and transcribe with 100% verbatim accuracy and exact word timestamps.
Dialect: ${dialect}.

CRITICAL GLOSSARY & VOCABULARY GROUNDING:
1. Brand & Entity Names:
   - Always transcribe the company name as 'Redfield' (STRICTLY 'Redfield', NEVER 'Redfilm', 'Red film', or 'Red-film'!).
2. French Vocabulary:
   - Always write 'vraiment' (NEVER 'vryment' or 'vriment').
   - In car detailing and PPF contexts, accurately transcribe: 'aucun résidu de colle' (NEVER 'aucun risque d'alcool' or 'la visibilité'!), 'sans trace de colle', 'premier test', 'la nouvelle technologie PPF', 'PPF'.
3. Darija & Arabic Speech Grounding:
   - When the speaker says 'ولا كاش خطر' (wla kach khatar), transcribe accurately in Darija as 'ولا كاش خطر' (NEVER invent or hallucinate French 'la visibilité'!).
   - When the speaker says 'النتيجة' (la natija), transcribe accurately in Arabic as 'النتيجة' (NEVER hallucinate French 'la recette'!).
   - In idioms like 'وكان الشرف لشركة...' always preserve 'الشرف' (never drop to 'شرف').
4. Do NOT write French loanwords phonetically in awkward Arabic letters (e.g. avoid 'برومي لو تيست'). If speaker uses standard French words (e.g. 'premier test', 'rendez-vous', 'projet', 'voiture', 'normal'), write them cleanly in standard French or natural Algerian terms.

Return STRICT JSON format only:
{
  "language": "ar-DZ",
  "text": "...",
  "segments": [
    {
      "id": 0,
      "start": 0.00,
      "end": 2.50,
      "text": "واش راك خويا",
      "words": [
        {"word": "واش", "start": 0.00, "end": 0.60},
        {"word": "راك", "start": 0.60, "end": 1.20},
        {"word": "خويا", "start": 1.20, "end": 2.50}
      ]
    }
  ]
}`;

return [{
  json: {
    contents: [
      {
        parts: [
          {
            inline_data: {
              mime_type: mimeType,
              data: base64Audio
            }
          },
          {
            text: prompt
          }
        ]
      }
    ],
    generationConfig: {
      temperature: 0.2,
      responseMimeType: 'application/json'
    },
    initial_prompt: initialPrompt,
