}];

// Parse Gemini Response and Perform French/Arabic Script Isolation & Strict 3-4 Word Grammatical Chunking
const response = $input.item.json;
const candidates = response.candidates || [];
if (!candidates.length) {
  throw new Error('Gemini API returned no candidates');
}

const rawText = candidates[0].content?.parts?.[0]?.text || '{}';
let data = {};
try {
  data = JSON.parse(rawText);
} catch (e) {
  const clean = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
  data = JSON.parse(clean);
}

const segments = data.segments || [];

// 1. Darija Spelling Normalizer
function sanitizeDarijaText(text) {
  if (!text) return "";
  let t = text
    .replace(/\bهكذاء\b/g, "هكذا")
    .replace(/\bهكداء\b/g, "هكدا")
    .replace(/\bهاكداء\b/g, "هاكدا")
    .replace(/\bهاكذاء\b/g, "هاكذا")
    .replace(/\bخلاصء\b/g, "خلاص")
    .replace(/\bصحاء\b/g, "صحة");
  // Restore dropped definite article in honor idioms
  t = t.replace(/\b(و?كان)\s+شرف\b/g, "$1 الشرف");
  t = t.replace(/\b(لي|لنا|عندي)\s+شرف\b/g, "$1 الشرف");
  // Fix Whisper acoustic hallucination in PPF / detailing context
  t = t.replace(/\baucun\s+risque\s+d['’]alcool\b/gi, "aucun résidu de colle");
  t = t.replace(/\brisque\s+d['’]alcool\b/gi, "résidu de colle");
  t = t.replace(/\bla\s+visibilit[ée]\s+ta[e3]\s+(?:al[- ]?)?d['’]?alcool\b/gi, "aucun résidu de colle");
  t = t.replace(/\b(?:al[- ]?)?d['’]?alcool\b/gi, "de colle");
  t = t.replace(/\bla\s+visibilit[ée]\b(?=\s*(?:ta[e3]|تاع|de|colle|ppf|هيكل))/gi, "résidu de colle");
  t = t.replace(/\bla\s+visibilit[ée]\b/gi, "ولا كاش خطر");
  t = t.replace(/\bvisibilit[ée]\b/gi, "كاش خطر");
  t = t.replace(/\bla\s+recette\b/gi, "النتيجة");
  t = t.replace(/\brecette\b(?=\s*(?:ta[e3]|تاع|ديال|اللي|كانت))/gi, "نتيجة");
  t = t.replace(/\brecette\b/gi, "النتيجة");
  t = t.replace(/\bvryment\b/gi, "vraiment");
  t = t.replace(/\bvriment\b/gi, "vraiment");
  t = t.replace(/\bRed\s*film[es]?\b/gi, "Redfield");
  t = t.replace(/\btechn\b/gi, "technologie");
  // Repair tokenizer clipped Latin words
  t = t.replace(/\b(le\s+|un\s+)?premi\b/gi, "$1premier");
  return t;
}

// 2. Flatten all words
const rawWords = [];
for (const seg of segments) {
  let segWords = seg.words || [];
  if (!segWords.length && seg.text) {
    const ws = seg.text.trim().split(/\s+/);
    const dur = Math.max(0.3, (seg.end - seg.start) / ws.length);
    const cur = seg.start;
    segWords = ws.map((w, i) => ({ word: w, start: cur + i * dur, end: cur + (i + 1) * dur }));
  }
  rawWords.push(...segWords);
}

// Multi-token acoustic hallucination sequence repairs
const filteredRawWords = [];
for (let i = 0; i < rawWords.length; i++) {
  const w1 = rawWords[i];
  const w1Txt = String(w1.word || '').trim();
  const w2 = i + 1 < rawWords.length ? rawWords[i + 1] : null;
  const w2Txt = w2 ? String(w2.word || '').trim() : '';

  if (['وكان', 'كان'].includes(w1Txt) && w2Txt === 'شرف') {
    filteredRawWords.push({ ...w1 });
    filteredRawWords.push({ ...w2, word: 'الشرف' });
    i++;
    continue;
  }

  if (w1Txt.toLowerCase() === 'la' && /^(?:visibilit[ée]|كاش خطر)$/i.test(w2Txt)) {
    filteredRawWords.push({ ...w1, word: 'ولا' });
    filteredRawWords.push({ ...w2, word: 'كاش خطر' });
    i++;
    continue;
  }

  if (w1Txt.toLowerCase() === 'la' && /^(?:recette|النتيجة)$/i.test(w2Txt)) {
    filteredRawWords.push({
      word: 'النتيجة',
      start: w1.start || 0,
      end: w2.end || ((w1.start || 0) + 0.5)
    });
    i++;
    continue;
  }

  if (w1Txt.toLowerCase() === 'red' && /^(?:film[es]?|Redfield)$/i.test(w2Txt)) {
    filteredRawWords.push({
      word: 'Redfield',
      start: w1.start || 0,
      end: w2.end || ((w1.start || 0) + 0.5)
    });
    i++;
    continue;
  }

  filteredRawWords.push(w1);
}
rawWords.length = 0;
rawWords.push(...filteredRawWords);

const LATIN_REGEX = /[a-zA-Z]/;
const ARABIC_REGEX = /[\u0600-\u06FF]/;

// 3. Split hybrid / fused script tokens (e.g. 'بهاد la' -> 'بهاد' + 'la')
const splitWords = [];
for (const w of rawWords) {
  const txt = sanitizeDarijaText(String(w.word || '').trim());
  const s = w.start || 0.0;
  const e = w.end || (s + 0.3);
  const dur = Math.max(0.1, e - s);

  if (LATIN_REGEX.test(txt) && ARABIC_REGEX.test(txt)) {
    const m = txt.match(/^([\u0600-\u06FF\s\-\u0640]+?)\s*([a-zA-Z].*)$/);
    if (m) {
      const p1 = m[1].trim();
      const p2 = m[2].trim();
      const splitRatio = p1.length / (p1.length + p2.length);
      const mid = Number((s + dur * splitRatio).toFixed(2));
      if (p1) splitWords.push({ word: p1, start: s, end: mid });
      if (p2) splitWords.push({ word: p2, start: mid, end: e });
      continue;
    }
  }

  // Merge isolated punctuation into previous word
  if ([",", "،", ".", "!", "?", "؛", ":"].includes(txt) && splitWords.length > 0) {
    const prev = splitWords[splitWords.length - 1];
    prev.word = `${prev.word}${txt}`;
    prev.end = Math.max(prev.end, e);
    continue;
  }

  splitWords.push({ word: txt, start: s, end: e });
}

// 4. Bind cohesive French expressions ('le premier', 'la nouvelle', 'par rapport')
const boundWords = [];
let i = 0;
while (i < splitWords.length) {
  const w = splitWords[i];
  const txt = w.word;
  const nextW = i + 1 < splitWords.length ? splitWords[i + 1] : null;
    // Bind negative existential copula: 'ما' + ('كاين', 'كاش', 'كانش')
  if (txt === "ما" && nextW && ["كاين", "كاش", "كانش"].includes(String(nextW.word || '').trim())) {
    boundWords.push({
      word: `ما ${String(nextW.word || '').trim()}`,
      start: w.start,
      end: nextW.end || (nextW.start + 0.3)
    });
    i += 2;
    continue;
  }

  const cleanTv = txt.replace(/^[^\w]+|[^\w]+$/g, '').toLowerCase();

  const wDur = (w.end || (w.start + 0.3)) - w.start;
  if (["la", "le", "les", "un", "une", "des", "du"].includes(cleanTv) && nextW && LATIN_REGEX.test(nextW.word) && wDur < 0.12) {
    boundWords.push({
      word: `${txt} ${nextW.word}`,
      start: w.start,
      end: nextW.end || (nextW.start + 0.3)
    });
    i += 2;
    continue;
  }

  if (txt.toLowerCase() === "par" && nextW && nextW.word.toLowerCase().startsWith("rapport")) {
    boundWords.push({
      word: `${txt} ${nextW.word}`,
      start: w.start,
      end: nextW.end || (nextW.start + 0.3)
    });
    i += 2;
    continue;
  }

  boundWords.push(w);
  i++;
}

// 5. Non-terminal tokens set & grammatical helper
const NON_TERMINAL_PARTICLES = new Set([
  "و", "ف", "ب", "ل", "في", "على", "من", "عن", "مع", "إلى", "الى",
  "ما", "لا", "لي", "اللي", "دي", "دو", "يا", "ها", "بهاد", "فهاد", "هاد",
  "بهذا", "هذا", "هادي", "يعني", "كيما", "باش", "باشما", "علاش", "كيفاش", "وين", "وقتاش",
  "بلي", "كي", "غير", "حتى", "ما كاين", "ماكاين", "ما كاش", "ماكاش", "ما كانش",
  "la", "le", "les", "un", "une", "des", "du", "de", "d'", "et", "ou",
  "en", "au", "aux", "par", "pour", "avec", "dans", "sur"
]);

function isNonTerminalToken(token) {
  const clean = String(token || "").replace(/^[^\w\u0600-\u06FF]+|[^\w\u0600-\u06FF]+$/g, "").toLowerCase().trim();
  if (NON_TERMINAL_PARTICLES.has(clean) || String(token || "").trim().endsWith("-") || String(token || "").trim().endsWith("ـ")) {
    return true;
  }
  if ((clean.startsWith("و") || clean.startsWith("ف")) && clean.length > 1 && NON_TERMINAL_PARTICLES.has(clean.slice(1))) {
    return true;
  }
  return false;
}

// 6. Isolate Latin and Arabic with forced chunk breaks & strict max 3-4 words
const TARGET_WORDS = 4;
const rawChunks = [];
let curChunk = [];
let curScript = null;

for (const w of boundWords) {
  const txt = String(w.word || '').trim();
  if (!txt) continue;

  const wScript = LATIN_REGEX.test(txt) ? 'latin' : 'arabic';

  let pauseGap = 0;
  if (curChunk.length > 0) {
    const prevEnd = curChunk[curChunk.length - 1].end || (curChunk[curChunk.length - 1].start + 0.3);
    pauseGap = w.start - prevEnd;
  }

  const prevText = curChunk.length > 0 ? String(curChunk[curChunk.length - 1].word || '').trim() : '';
  const prevClean = prevText.replace(/^[^\w\u0600-\u06FF]+|[^\w\u0600-\u06FF]+$/g, "").toLowerCase().trim();
  const hasMajorStop = [".", "!", "?", "،", ","].some(p => prevText.endsWith(p));

    // Inseparable Noun + Adjective / Genitive construct (e.g. 'المستوى الوطني', 'المستوى الأفريقي', 'الهيكل تاعها', 'السيارة الشخصية')
  const isNounAdjective = (NOUN_PATTERNS.includes(prevClean) || NOUN_PATTERNS.includes(prevBase)) && (txt.startsWith("ال") || txt.startsWith("الإ") || txt.startsWith("الأ") || txt.startsWith("تاع") || txt.startsWith("ديال"));

  const isInseparable = (["ما كاين", "ماكاين", "ما كاش", "ماكاش", "ما كانش"].includes(prevClean) && (txt.startsWith("حتى") || !isNonTerminalToken(txt))) || (prevClean === "بلي" && (txt.startsWith("ما") || txt === "ما")) || (prevClean === "حتى" && !isNonTerminalToken(txt)) || isNounAdjective;

  // Coordinating conjunction boundary (e.g. 'والمستوى', 'والنتيجة', 'وعلى', 'وهادي')
  const isConjunctionBoundary = (curChunk.length >= 2 && (txt.startsWith("و") || txt.startsWith("ف")) && txt.length > 2 && !isNounAdjective);

  // Relative clause boundary (e.g. 'اللي', 'اللي كانت')
  const isRelativeClauseBoundary = (curChunk.length >= 2 && (txt.startsWith("اللي") || txt.startsWith("الي")));

  let shouldBreak = false;
  if (curChunk.length > 0) {
    const chunkWordsText = curChunk.map(cw => String(cw.word ||

));
    const effectiveLimit = isParallelCoordination ? (TARGET_WORDS + 1) : TARGET_WORDS;

    if (pauseGap > 0.50) {
      shouldBreak = true; // Hard silence boundary
    } else if (isConjunctionBoundary) {
      shouldBreak = true;
    } else if (isRelativeClauseBoundary) {
      shouldBreak = true;
    } else if (isInseparable) {
      shouldBreak = false;
    } else if (curChunk.length >= effectiveLimit) {
      shouldBreak = true; // Strict 3-4 words max (5 for parallel clauses)
    } else if (curChunk.length >= 2 && isNonTerminalToken(txt)) {
      shouldBreak = true; // Break before preposition/particle to keep phrases natural
    } else if (hasMajorStop && curChunk.length >= 2) {
      shouldBreak = true;
    }
  }

  if (shouldBreak && curChunk.length > 0) {
    rawChunks.push({ script: curScript, words: curChunk });
    curChunk = [];
  }

  curChunk.push(w);
  curScript = wScript;
}

if (curChunk.length > 0) {
  rawChunks.push({ script: curScript, words: curChunk });
}

// 7. Anti-orphan pass: only merge tiny 1-word fragments if SAME script, gap <= 0.40s, and combined <= 4 words
const structuredChunks = [];
for (const rc of rawChunks) {
  if (!rc.words || !rc.words.length) continue;
  if (structuredChunks.length > 0) {
    const prev = structuredChunks[structuredChunks.length - 1];
    const prevEnd = prev.words[prev.words.length - 1].end || (prev.words[prev.words.length - 1].start + 0.3);
    const gap = rc.words[0].start - prevEnd;

    if (prev.script === rc.script && gap <= 0.40 && (prev.words.length + rc.words.length <= TARGET_WORDS) && (rc.words.length === 1 || prev.words.length === 1)) {
      prev.words.push(...rc.words);
      prev.end = rc.words[rc.words.length - 1].end || (rc.words[rc.words.length - 1].start + 0.3);
      continue;
    }
  }

  structuredChunks.push({
    script: rc.script,
    words: rc.words,
    start: rc.words[0].start,
    end: rc.words[rc.words.length - 1].end || (rc.words[rc.words.length - 1].start + 0.3)
  });
}

return [{
  json: {
    transcription: data,
    chunks: structuredChunks
  }
}];

// Build Animated ASS Subtitles using Pre-Isolated Script Chunks with Uniform 2D Spring Pop Physics
const itemJson = $input.item.json;
const data = itemJson.transcription || {};
const chunks = itemJson.chunks || [];

function formatAssTime(seconds) {
  const s = Math.max(0, seconds || 0);
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = Math.floor(s % 60);
  const cs = Math.min(99, Math.round((s - Math.floor(s)) * 100));
  return `${h}:${String(m).padStart(2, '0')}:${String(sec).padStart(2, '0')}.${String(cs).padStart(2, '0')}`;
}

let assContent = `[Script Info]
Title: Darija Subtitles Generator
ScriptType: v4.00+
WrapStyle: 0
ScaledBorderAndShadow: yes
YCbCr Matrix: TV.709
PlayResX: 1080
PlayResY: 1920

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Default,Cairo,58,&H00FFFFFF&,&H0000E6FF&,&H00000000&,&H23000000&,-1,0,0,0,100,100,0,0,1,3.5,2.5,2,30,30,960,-1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
`;

// Build events with uniform 2D Remotion-calibrated spring pop (fscx120 + fscy120) and strict silence clearance
for (let cIdx = 0; cIdx < chunks.length; cIdx++) {
  const chunkObj = chunks[cIdx];
  const chunk = chunkObj.words || [];
  if (!chunk.length) continue;

  const isRtl = chunkObj.script === "arabic";
  const nextChunkStart = cIdx + 1 < chunks.length ? chunks[cIdx + 1].start : null;

  for (let j = 0; j < chunk.length; j++) {
    const active = chunk[j];
    let wEnd;
    if (j + 1 < chunk.length) {
      const nextW = chunk[j + 1];
      const natEnd = active.end || (active.start + 0.3);
      const gap = nextW.start - natEnd;
      if (gap > 0.50) {
        wEnd = natEnd + 0.25;
      } else {
        wEnd = nextW.start;
      }
    } else {
      const naturalEnd = active.end || (active.start + 0.3);
      const minHold = active.start + 0.70;
      if (nextChunkStart !== null) {
        const gap = nextChunkStart - naturalEnd;
        if (gap > 0.50) {
          wEnd = Math.max(active.start + 0.3, naturalEnd + 0.35);
        } else {
          wEnd = Math.min(nextChunkStart - 0.05, Math.max(naturalEnd, minHold));
        }
      } else {
        wEnd = Math.max(naturalEnd, minHold);
      }
    }

    // Enforce max duration rule of 2.5 seconds
    wEnd = Math.min(active.start + 2.5, Math.max(active.start + 0.25, wEnd));

    const startStr = formatAssTime(active.start);
    const endStr = formatAssTime(wEnd);
    const durMs = Math.max(120, Math.floor((wEnd - active.start) * 1000));

    // Remotion-calibrated 4-stage uniform 2D harmonic spring: overshoot (120%) -> recoil (108%) -> micro-bounce (114%) -> settle (100%)
    const t1 = Math.max(35, Math.min(Math.floor(durMs * 0.32), 95));
    const t2 = Math.max(t1 + 25, Math.min(Math.floor(durMs * 0.62), 185));
    const t3 = Math.max(t2 + 25, Math.min(Math.floor(durMs * 0.85), 260));

    // Active word physically springs forward and remains enlarged at 1.18x (118%) while spoken
    const activePopTag = `\\c&H0000E6FF&\\blur1.8\\fscx100\\fscy100\\t(0,${t1},0.45,\\fscx128\\fscy128)\\t(${t1},${t2},1.4,\\fscx118\\fscy118)`;
    const normalPriTag = `\\c&H00FFFFFF&\\blur0.8\\fscx100\\fscy100`;

    const formatted = chunk.map((w, idx) => {
      const rawW = String(w.word || '');
      const hasLatin = /[a-zA-Z]/.test(rawW);
      const cleanWord = hasLatin ? `\\u200E${rawW}\\u200E` : rawW;
      return idx === j
        ? `{${activePopTag}}${cleanWord}{${normalPriTag}}`
        : `{${normalPriTag}}${cleanWord}`;
    }).join(' ');

    const lineText = isRtl ? `\\u200F${formatted}` : `\\u200E${formatted}`;
    assContent += `Dialogue: 0,${startStr},${endStr},Default,,0,0,0,,${lineText}\n`;
  }
}

return [{
  json: {
    transcription: data,
    chunks: chunks,
    assContent: assContent
  }
}];
